1	// Land a task's delivered pull request under the REPO's delivery settings — the
2	// single home for the auto-merge nuances every PR-delivering task shares. These
3	// helpers were built inside the baselining worker (#455/#565/#649/#677/#690);
4	// they live here because the other landing tasks hit the identical failure
5	// shapes (an arm rejected "clean status" on an ungated base stranding a green PR
6	// forever), and two copies of this precedence is exactly the drift the corpus
7	// forbids.
8	//
9	// The contract that keeps tasks simple: a task declares only its outcome CEILING
10	// (`automerge` — what it MAY land; merge-policy.mjs owns whether a granular
11	// policy covers the actual diff). Whether the PR actually
12	// lands unreviewed is the MEMBER REPO's call — `dailyClaudiniteUpdatesRequirePrReview`
13	// in its settings file, where `true` degrades every authorized landing to review
14	// (member config wins, per-project-scheduling DESIGN §1). Tasks stay
15	// unaware of that setting by construction: they hand their PR to landDelivery()
16	// (directly, or through deliver-generated.mjs) and the repo-shape nuances stay
17	// here:
18	//
19	//   - `review` member          → the PR is opened and LEFT — never armed, never merged.
20	//   - no pull_request CI at all → MERGE directly. GitHub's auto-merge is a queue
21	//     for checks; with nothing to queue behind, the arm is rejected ("Pull
22	//     request is in clean status") every time, and while that rejection was
23	//     swallowed a repo that asked for auto-merge got no merge at all.
24	//   - CI present, but the base branch REQUIRES nothing → the arm is equally
25	//     doomed (same clean-status rejection, #677): skip it, wait for this run's
26	//     own dispatched evidence, and land on it (verify-then-merge).
27	//   - a base gate present — or unreadable, which is never read as absent → ARM,
28	//     with the landing poll as fallback when the arm is rejected (auto-merge
29	//     disabled repo-side, or a pull_request run parked at `action_required`).
30	//
31	// A branch pushed and a PR opened over the Action's GITHUB_TOKEN emit no
32	// pull_request run of their own (GitHub's recursion guard, #565), so
33	// landDelivery also STARTS the PR's checks via workflow_dispatch before deciding
34	// anything — the checks an arm would wait on must exist to conclude.
35	//
36	// The AGENT lane (executor subagents, MCP writes) cannot run this module; its
37	// prose twin is `deliver-pr.md` beside this file, and the two must keep saying
38	// the same thing — a nuance changed here changes there in the same commit.
39	//
40	// DISPOSAL lives here too (`openDeliveredPull` / `disposeOpenPull`). It began as
41	// baselining's private close-and-recut, kept in that worker while it was the only
42	// task that re-cut a per-cycle branch. The update flows re-cut one exactly the same
43	// way, and #787 is what the second copy would have cost: the update runner promised
44	// "leaving it open for the next run to dispose of" with no code anywhere that could
45	// keep the promise, so a PR its cycle could not land was superseded by a duplicate
46	// the next cycle opened instead. One precedence, one home.
47	
48	import { taskTrailer } from './task-trailer.mjs';
49	
50	const API = 'https://api.github.com';
51	
52	// The squash-merge request body. THE MERGE COMMIT is what lands on the default
53	// branch, so it — not only the branch's own commits — has to say which task
54	// wrote it, or the `commits` collector reads a task's own delivery as the
55	// project moving and every task keeps its neighbours awake. `commit_message`
56	// replaces the squash body GitHub would compose; the title it leaves alone, so
57	// the merge still reads as the PR it was.
58	//
59	// A caller with no task to name (a member's own script, a hand-run worker) sends
60	// the plain merge, and the older author/title exclusions classify it as they
61	// always did.
62	const squashBody = (task) => {
63	  const trailer = taskTrailer(task);
64	  return { merge_method: 'squash', ...(trailer ? { commit_message: trailer } : {}) };
65	};
66	
67	async function gh(token, path, { method = 'GET', body } = {}) {
68	  const res = await fetch(`${API}${path}`, {
69	    method,
70	    headers: {
71	      authorization: `Bearer ${token}`,
72	      accept: 'application/vnd.github+json',
73	      'x-github-api-version': '2022-11-28',
74	      ...(body ? { 'content-type': 'application/json' } : {}),
75	    },
76	    body: body ? JSON.stringify(body) : undefined,
77	  });
78	  let json = null;
79	  try { json = await res.json(); } catch { /* empty body */ }
80	  return { status: res.status, json };
81	}
82	
83	// --- the member's delivery preference ----------------------------------------
84	
85	// The member's delivery preference, normalized. `push`/`auto` → auto-merge and
86	// `pr` → review are the permanent legacy aliases (the maintenance-lane tolerance);
87	// anything else is invalid (null) and fails the run rather than guessing.
88	export function normalizeDelivery(raw) {
89	  const v = String(raw ?? '').trim();
90	  if (v === 'auto-merge' || v === 'auto' || v === 'push') return 'auto-merge';
91	  if (v === 'review' || v === 'pr') return 'review';
92	  return null;
93	}
94	
95	// The default a repo gets when it never declared one.
96	export const DEFAULT_DELIVERY = 'auto-merge';
97	
98	// @deprecated — the `maintenance.delivery` resolution, kept callable for the
99	// fielded workers that still import it (an `updates/*`-class surface: a member's
100	// vendored worker is a cycle behind the flows that rewrote its declaration). New
101	// callers ask `deliveryFor` below, which reads the current key.
102	//
103	// `maintenance.delivery` was always EXPLICIT — but a key that is simply absent is
104	// DRIFT, not an error. A repo adopted before the key existed, or one whose key
105	// was hand-removed, would otherwise fail its scheduled tasks every night forever
106	// with nothing that could ever fix it. So: resolve to the default and carry on —
107	// `materialize: true` tells the one caller that CAN write the repair to do so.
108	//
109	// An UNRECOGNIZED value is a different thing entirely: someone wrote an intent
110	// this code cannot honour, and silently substituting a default would deliver
111	// the opposite of what they asked for. That still fails the run (delivery: null).
112	export function resolveDelivery(raw) {
113	  if (raw == null || String(raw).trim() === '') {
114	    return { delivery: DEFAULT_DELIVERY, materialize: true };
115	  }
116	  return { delivery: normalizeDelivery(raw), materialize: false };
117	}
118	
119	// @deprecated with `resolveDelivery` above, and kept callable for the same reason.
120	export function deliveryFromChecks(text) {
121	  let parsed = null;
122	  try { parsed = JSON.parse(text ?? 'null'); } catch { /* unreadable → absent */ }
123	  return resolveDelivery(parsed?.maintenance?.delivery);
124	}
125	
126	// THE MEMBER'S DELIVERY, from its parsed settings. One override, one direction:
127	// `dailyClaudiniteUpdatesRequirePrReview: true` leaves the PR for a human, and
128	// anything else — the key absent, which is the normal shape — lands it. That
129	// asymmetry is the point of #1252: every member wanted the same thing, so the
130	// setting materialized into every declaration said nothing, and the one repo that
131	// wants review is the one that should have to say so.
132	//
133	// The retired `maintenance.delivery` is read underneath for a member the rename
134	// record has not reached. Unparsable or absent settings resolve like an absent
135	// key — auto-merge, not failure: the file's integrity is check_the_world's
136	// problem, not the delivery step's.
137	export function deliveryFor(settings) {
138	  if (settings?.dailyClaudiniteUpdatesRequirePrReview === true) return 'review';
139	  if (settings?.dailyClaudiniteUpdatesRequirePrReview === undefined
140	      && normalizeDelivery(settings?.maintenance?.delivery) === 'review') return 'review';
141	  return DEFAULT_DELIVERY;
142	}
143	
144	// The same, from the raw TEXT of a settings file — the shape a caller reading the
145	// file off a git blob has in hand.
146	export function deliveryForText(text) {
147	  let parsed = null;
148	  try { parsed = JSON.parse(text ?? 'null'); } catch { /* unreadable → absent */ }
149	  return deliveryFor(parsed);
150	}
151	
152	// --- CI dispatch on the delivered PR (#565) -----------------------------------
153	// The GITHUB_TOKEN push/PR-open emits no pull_request run (GitHub's recursion
154	// guard), so the delivery starts the PR's checks itself: dispatch every workflow
155	// that WOULD have run on pull_request and CAN be dispatched.
156	//
157	// "Suppresses" is only half true, and the other half is #455/#205/#95: on some
158	// members GitHub CREATES the pull_request run and parks it at `action_required`
159	// awaiting an approval nobody clicks. The dispatch above still supplies the real
160	// green, but the parked run is what auto-merge refuses over — which is why
161	// arming is not the end of the story and pullDisposition exists.
162	//
163	// Reading the triggers is a best-effort TEXTUAL scan of a workflow's top-level
164	// `on:` block (no YAML parser in the corpus). It covers the shapes workflows
165	// actually use: a block map of trigger keys (with or without nested config), the
166	// inline scalar, and the inline list.
167	export function workflowTriggers(yaml) {
168	  const lines = String(yaml ?? '').split('\n');
169	  const onAt = lines.findIndex((l) => /^(['"]?)on\1\s*:/.test(l));
170	  if (onAt === -1) return [];
171	  const inline = lines[onAt].replace(/^(['"]?)on\1\s*:/, '').replace(/#.*$/, '').trim();
172	  if (inline) return inline.replace(/[[\]]/g, '').split(',').map((s) => s.trim()).filter(Boolean);
173	  const triggers = [];
174	  let childIndent = null;
175	  for (let i = onAt + 1; i < lines.length; i += 1) {
176	    const line = lines[i];
177	    if (!line.trim() || line.trim().startsWith('#')) continue;
178	    const indent = line.length - line.trimStart().length;
179	    if (indent === 0) break;                        // next top-level key — on: is done
180	    childIndent = childIndent ?? indent;            // first child fixes the trigger level
181	    if (indent !== childIndent) continue;           // nested config under a trigger
182	    const m = /^([A-Za-z_]+)\s*:/.exec(line.trim());
183	    if (m) triggers.push(m[1]);
184	  }
185	  return triggers;
186	}
187	
188	// The dispatch plan over the repo's workflow files ({name, content} each):
189	// `dispatch` — runs on pull_request AND carries workflow_dispatch (start these);
190	// `missing`  — runs on pull_request but CANNOT be dispatched (name these in the
191	// log: adding `workflow_dispatch:` to that file's `on:` is the owner's one-line
192	// fix, and silence here would read as "no CI expected" when CI was expected).
193	// A workflow with no pull_request trigger is never touched — dispatchable-but-
194	// unrelated workflows (a release orchestrator, say) must not fire on a delivery.
195	export function ciDispatchPlan(files) {
196	  const dispatch = [];
197	  const missing = [];
198	  for (const { name, content } of files ?? []) {
199	    const triggers = workflowTriggers(content);
200	    if (!triggers.includes('pull_request')) continue;
201	    (triggers.includes('workflow_dispatch') ? dispatch : missing).push(name);
202	  }
203	  return { dispatch, missing };
204	}
