206	// The I/O half of the CI dispatch: read the workflow files as they exist ON THE
207	// DELIVERED BRANCH (the delivery may itself have changed them), plan with
208	// ciDispatchPlan, POST a dispatch per selected workflow, and log every outcome —
209	// a silent no-checks PR is exactly the failure mode this exists to close. Needs
210	// the scheduler workflow's `actions: write` (a read-only token 403s the POST
211	// silently — the store-release lesson).
212	// Returns { dispatch, missing, started }: `dispatch`/`missing` are the PLAN
213	// (what the tree says should run), `started` the dispatches GitHub actually
214	// accepted (204). The landing poll must wait only on `started` — a POST that
215	// 403'd (the scheduler workflow missing `actions: write`, the canon's own copy
216	// on 2026-08-08) starts nothing, and counting the plan had the poll waiting for
217	// a run that could never come.
218	export async function dispatchCiRuns({ token, repo, branch, log = console.log }) {
219	  const ref = encodeURIComponent(branch);
220	  const { json: dir } = await gh(token, `/repos/${repo}/contents/.github/workflows?ref=${ref}`);
221	  const files = [];
222	  for (const entry of Array.isArray(dir) ? dir : []) {
223	    if (!/\.ya?ml$/.test(entry.name ?? '')) continue;
224	    const { json } = await gh(token, `/repos/${repo}/contents/.github/workflows/${entry.name}?ref=${ref}`);
225	    files.push({ name: entry.name, content: json?.content ? Buffer.from(json.content, 'base64').toString('utf8') : '' });
226	  }
227	  const { dispatch, missing } = ciDispatchPlan(files);
228	  for (const name of missing) {
229	    log(`${name} runs on pull_request but has no workflow_dispatch trigger — `
230	      + 'cannot start it on the delivered PR; add `workflow_dispatch:` under its `on:` to let the delivery run it');
231	  }
232	  if (!dispatch.length && !missing.length) {
233	    log('no pull_request-triggered workflow — the delivered PR has no checks to wait for');
234	  }
235	  const started = [];
236	  for (const name of dispatch) {
237	    const res = await gh(token, `/repos/${repo}/actions/workflows/${name}/dispatches`, {
238	      method: 'POST', body: { ref: branch },
239	    });
240	    if (res.status === 204) { started.push(name); log(`dispatched ${name} on ${branch} — the delivered PR gets its checks`); }
241	    else {
242	      log(`could not dispatch ${name} on ${branch} (${res.status})`
243	        + (res.status === 403 ? ' — the scheduler workflow needs `actions: write` (a read token 403s this POST silently)' : ''));
244	    }
245	  }
246	  return { dispatch, missing, started };
247	}
