249	// --- opening the PR ------------------------------------------------------------
250	
251	// Why the PR-open POST must be status-checked, as a pure predicate: null when
252	// the PR was created, else the message to fail on.
253	//
254	// This is the one call whose silent failure is invisible AND self-perpetuating:
255	// a cycle that pushes its branch but fails to open the PR leaves nothing for the
256	// next cycle to find, branches pile up nightly, and the run still reports `ok`
257	// because nothing read the status. The usual cause is repo-level and invisible
258	// from here — "Allow GitHub Actions to create and approve pull requests" is off
259	// and the POST 403s — so the message names that remedy rather than leaving a
260	// bare status code.
261	export function pullCreateError(status, json) {
262	  if (status === 201 && json?.number) return null;
263	  const detail = json?.message ?? `HTTP ${status}`;
264	  return `${detail} — if this is the Actions PR permission, enable Settings → Actions`
265	    + ' → General → "Allow GitHub Actions to create and approve pull requests"';
266	}
