299	// What the base branch requires before a merge, from the two reads the Action's
300	// GITHUB_TOKEN can make: the branch's `protected` flag and the ruleset rules
301	// that apply to it (deliberately NOT /branches/{base}/protection, which wants
302	// admin). Rule types that queue a PR gate it; rules about pushes and deletions
303	// do not. An unreadable answer is UNKNOWN, never absent — unknown assumes a
304	// gate, so the caller arms rather than merging past a gate it cannot see.
305	const GATING_RULE_TYPES = ['pull_request', 'required_status_checks', 'merge_queue', 'required_deployments'];
306	export function classifyMergeGate({ branchStatus, branchJson, rulesStatus, rulesJson }) {
307	  if (branchStatus !== 200 || typeof branchJson?.protected !== 'boolean') return 'unknown';
308	  if (branchJson.protected) return 'present';
309	  if (rulesStatus !== 200 || !Array.isArray(rulesJson)) return 'unknown';
310	  return rulesJson.some((r) => GATING_RULE_TYPES.includes(r?.type)) ? 'present' : 'absent';
311	}
