313	export async function readMergeGate(token, repo, base) {
314	  const branch = await gh(token, `/repos/${repo}/branches/${encodeURIComponent(base)}`);
315	  const rules = await gh(token, `/repos/${repo}/rules/branches/${encodeURIComponent(base)}`);
316	  return classifyMergeGate({
317	    branchStatus: branch.status, branchJson: branch.json,
318	    rulesStatus: rules.status, rulesJson: rules.json,
319	  });
320	}
