322	// --- judging a PR by the runs on its head (#455/#205/#95) ---------------------
323	// Arming is best-effort and can fail PERMANENTLY, so "arm and move on" is not a
324	// delivery guarantee. Two shapes, both observed across the fleet, both leaving a
325	// green PR open forever:
326	//
327	//   1. GATED CI. GitHub CREATES the pull_request run for a GITHUB_TOKEN push and
328	//      parks it at conclusion `action_required`, pending a human "Approve and
329	//      run" that nobody is watching for. The run never executes, so it never
330	//      reports; `enablePullRequestAutoMerge` then refuses the PR with "in
331	//      unstable status (required checks are failing)". Meanwhile the
332	//      workflow_dispatch run started on the SAME head sha ran and passed. So CI
333	//      did pass; only the phantom gated run says otherwise.
334	//   2. AUTO-MERGE OFF. The repo never enabled Settings → General → "Allow
335	//      auto-merge", so the mutation is rejected outright no matter how green.
336	//
337	// Both are settled by the same evidence: the runs on the PR's own head sha. If
338	// CI has CONCLUDED and nothing actually failed, the content on that sha is
339	// verified and `auto-merge` means merge it. A gated `action_required` run is not
340	// a failure — it is a run that never happened.
341	//
342	// Deliberately conservative about MERGING, because that bypasses the arm:
343	//   - Anything still queued/running → `wait`. Never merge mid-flight.
344	//   - Any real failure (failure / timed_out / cancelled / startup_failure), or no
345	//     successful run to stand on → `close`: NOT a merge, and equally not a reuse.
346	//     (What `close` means is the CALLER's policy — a delivery closes and re-cuts
347	//     its per-cycle branch; a landing pass just leaves the PR standing.)
348	//
349	// A `review` member's PR is the owner's to act on, on their own clock — never
350	// merged, and never closed out from under them either.
351	export const REAL_FAILURES = ['failure', 'timed_out', 'cancelled', 'startup_failure'];
352	
353	export function pullDisposition({ delivery, runs }) {
354	  if (delivery !== 'auto-merge') return 'keep';
355	  const list = (runs ?? []).filter(Boolean);
356	  if (list.some((r) => r.status !== 'completed')) return 'wait';
357	  if (list.some((r) => REAL_FAILURES.includes(r.conclusion))) return 'close';
358	  if (!list.some((r) => r.conclusion === 'success')) return 'close';
359	  return 'merge';
360	}
361	
362	// Why the merge had to happen here rather than through the arm. The log line has
363	// to name which shape this was, or the repo misconfiguration behind it stays
364	// invisible — and it is a REPO setting, so only a human can retire it.
365	export function mergeReason(runs) {
366	  // The no-remedy shape names no setting (#677): on a base that requires
367	  // nothing, landing here IS the design, and sending an owner to fix something
368	  // already correct is worse than saying nothing.
369	  return (runs ?? []).some((r) => r?.conclusion === 'action_required')
370	    ? 'its pull_request run is parked at action_required (never ran) while the dispatched run passed'
371	    + ' — check Settings → Actions → General → workflow-approval requirements'
372	    : 'its dispatched checks concluded green and nothing on the base branch queues an auto-merge';
373	}
374	
375	// Why a PR was left (or closed) rather than merged — the same visibility
376	// argument, for the case that matters more: a member whose CI is genuinely red.
377	export function failureSummary(runs) {
378	  const list = (runs ?? []).filter(Boolean);
379	  const failed = list.filter((r) => REAL_FAILURES.includes(r?.conclusion));
380	  if (failed.length) return `failing CI: ${failed.map((r) => `${r.name} ${r.conclusion}`).join(', ')}`;
381	  // A run still going at the bound is a statement about the CLOCK, not a verdict
382	  // on the runs, and conflating the two sent a reader to a repository-settings
383	  // diagnosis for a repo where nothing was misconfigured (#1026). Name what is
384	  // still moving, so a member whose CI outruns the budget is visible as itself.
385	  const inFlight = list.filter((r) => r?.status && r.status !== 'completed');
386	  if (inFlight.length) {
387	    return 'still running at the landing bound: '
388	      + `${inFlight.map((r) => `${r.name} ${r.status}`).join(', ')} — it lands next cycle`;
389	  }
390	  return 'no successful run on its head sha';
391	}
