393	// --- disposing of the PREVIOUS cycle's delivery (#787) ------------------------
394	// A task that delivers on a per-cycle branch must dispose of the last cycle's PR
395	// before cutting its own, or the two accumulate: the incumbent can no longer merge
396	// (its diff is landed by the newcomer) and nothing else will ever close it.
397	//
398	// Found by head-branch PREFIX, because the name carries a per-cycle date and seed —
399	// the prefix is what identifies the family. The whole PR is returned rather than its
400	// ref alone: disposal needs its number and head sha.
401	export function openDeliveredPull(pulls, prefix) {
402	  return (pulls ?? []).find((pr) => String(pr?.head?.ref ?? '').startsWith(prefix)) ?? null;
403	}
404	
405	// The I/O half: read the runs on that PR's head, decide with the SAME predicate the
406	// landing poll uses, and either merge it (its content was verified — only the arm
407	// failed) or close it and delete its branch so this cycle re-cuts from scratch.
408	//
409	// Returns which disposal happened, because the three outcomes leave the caller in
410	// three different places and a bare null conflates two of them:
411	//
412	//   'kept'   — it still stands (a `wait`, a `review` member, or a failed attempt).
413	//              Do not deliver on top of it; leaving ONE PR alive is the whole point.
414	//   'closed' — the way is clear and main is unchanged, so this cycle re-cuts.
415	//   'merged' — the way is clear but MAIN JUST MOVED, and this job's checkout predates
416	//              it. Converging on that stale tree would re-deliver a diff already on
417	//              main, which GitHub refuses ("No commits between…") and which would in
418	//              any case be the duplicate this whole helper exists to prevent. The
419	//              caller ends its cycle instead; the next one starts from fresh main.
420	//
421	// Best-effort throughout: anything unreadable or unmergeable leaves the PR as it was
422	// found, because a cycle that cannot dispose of the incumbent must skip rather than
423	// pile a second PR on top of it.
424	export async function disposeOpenPull({ token, repo, pr, delivery, task = null, log = console.log }) {
425	  const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha ?? ''}&per_page=100`);
426	  if (status !== 200) {
427	    log(`could not read the runs for PR #${pr.number}'s head (HTTP ${status}) — leaving it`);
428	    return 'kept';
429	  }
430	  const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
431	  const disposition = pullDisposition({ delivery, runs });
432	
433	  if (disposition === 'keep' || disposition === 'wait') {
434	    log(`keeping PR #${pr.number} (${disposition})`);
435	    return 'kept';
436	  }
437	
438	  if (disposition === 'merge') {
439	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
440	      method: 'PUT', body: squashBody(task),
441	    });
442	    if (res.status === 200) {
443	      log(`merged PR #${pr.number} — ${mergeReason(runs)}`);
444	      await deleteBranch({ token, repo, ref: pr.head?.ref, log });
445	      return 'merged';
446	    }
447	    log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
448	      + ' — closing it instead; the converge is idempotent and this cycle re-cuts it');
449	  }
450	
451	  // Closed, not left to rot: whatever went wrong on that head, the next converge
452	  // reproduces the same content from the same inputs. Named in the log because a
453	  // member closing its delivery every single cycle is a repo whose CI needs a human,
454	  // and the pattern has to be visible to be noticed.
455	  const closed = await gh(token, `/repos/${repo}/pulls/${pr.number}`, { method: 'PATCH', body: { state: 'closed' } });
456	  if (closed.status !== 200) {
457	    log(`could not close PR #${pr.number} (${closed.status}) — leaving it and skipping this cycle`);
458	    return 'kept';
459	  }
460	  log(`closed PR #${pr.number} — it did not land (${failureSummary(runs)}); re-cutting this cycle`);
461	  await deleteBranch({ token, repo, ref: pr.head?.ref, log });
462	  return 'closed';
463	}
