521	// Arm native auto-merge on a PR (by node id) via the GraphQL mutation — the REST
522	// `PUT /merge` would merge NOW, ignoring pending checks; this waits for them.
523	export async function enableAutoMerge(token, pullRequestId) {
524	  const query = 'mutation($id:ID!){enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}){pullRequest{id}}}';
525	  const res = await fetch(`${API}/graphql`, {
526	    method: 'POST',
527	    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
528	    body: JSON.stringify({ query, variables: { id: pullRequestId } }),
529	  });
530	  const json = await res.json().catch(() => null);
531	  if (json?.errors?.length) throw new Error(json.errors[0].message);
532	}
