534	// Tidy the ref behind a merged (or disposed) PR — a dead branch left on the
535	// remote is litter that accumulates one per run. Never fatal: the branch is not
536	// the deliverable.
537	export async function deleteBranch({ token, repo, ref, log = console.log }) {
538	  if (!ref) return;
539	  const res = await gh(token, `/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' });
540	  if (res.status !== 204) log(`could not delete branch ${ref} (HTTP ${res.status})`);
541	}
542	
543	const sleep = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });
544	
545	// The I/O half of same-run landing: poll this PR's head sha until its runs have
546	// concluded, then merge on the same evidence disposal would use a cycle later.
547	// Returns true iff it merged. Best-effort throughout — every failure path leaves
548	// the PR exactly as the arm left it, which is what the next run expects.
549	export async function landNow({ token, repo, pr, delivery, expected = 0, task = null, log = console.log }) {
550	  const started = Date.now();
551	  for (;;) {
552	    const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha ?? ''}&per_page=100`);
553	    if (status !== 200) {
554	      log(`could not read this run's checks for PR #${pr.number} (HTTP ${status}) — leaving it for the next run`);
555	      return false;
556	    }
557	    const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
558	    const attempt = landAttempt({ delivery, runs, expected, elapsedMs: Date.now() - started });
559	
560	    if (attempt === 'poll') { await sleep(LAND_POLL_MS); continue; }
561	    if (attempt === 'give-up') {
562	      log(`PR #${pr.number} not landable this run (${failureSummary(runs)})`
563	        + ' — leaving it open for the next run to dispose of');
564	      return false;
565	    }
566	
567	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
568	      method: 'PUT', body: squashBody(task),
569	    });
570	    if (res.status === 200) {
571	      log(`merged PR #${pr.number} in-cycle — ${mergeReason(runs)}`);
572	      await deleteBranch({ token, repo, ref: pr.head?.ref, log });
573	      return true;
574	    }
575	    log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
576	      + ' — leaving it for the next run');
577	    return false;
578	  }
579	}
