581	// The whole landing, composed — what a task's delivery calls once its PR exists.
582	// Dispatch the PR's checks (they establish `hasPrCi`, the fact deliveryAction
583	// turns on), read what the base requires, then merge / land / arm per the
584	// decision — with the landing poll as fallback for a failed arm. `pr` must carry
585	// the CURRENT head ({ number, node_id, head: { ref, sha } }): after a force-push,
586	// a stale sha polls runs that will never conclude.
587	//
588	// Returns { merged, action }. `action: 'none'` is the review member — the PR
589	// stands, deliberately, and that is a delivered outcome, not a failure.
590	export async function landDelivery({ token, repo, base, pr, delivery, task = null, log = console.log }) {
591	  // Start the PR's checks FIRST — the GITHUB_TOKEN push/open emitted no
592	  // pull_request event, so without this the PR has no runs (#565). AFTER the
593	  // push, so the dispatched runs execute the branch's own head. Best-effort: a
594	  // dispatch failure must not fail the delivery that was already pushed. Run for
595	  // review members too — their owner wants green checks to review against.
596	  const ci = await dispatchCiRuns({ token, repo, branch: pr.head?.ref, log })
597	    .catch((e) => { log(`CI dispatch on ${pr.head?.ref} failed: ${e.message}`); return null; });
598	  const hasPrCi = ci ? ci.dispatch.length + ci.missing.length > 0 : true; // unknown → assume CI, never merge blind
599	  // How many verification runs this delivery ACTUALLY started on the head — what
600	  // the landing poll waits to see registered before it judges anything
601	  // (landAttempt). `started`, never the plan: a rejected dispatch POST starts
602	  // nothing, and waiting on the plan wedges the poll against a run that can
603	  // never come.
604	  const expected = ci?.started?.length ?? 0;
605	
606	  const gate = await readMergeGate(token, repo, base).catch(() => 'unknown');
607	  const action = deliveryAction({ delivery, hasPrCi, gate });
608	  let merged = false;
609	
610	  if (action === 'merge') {
611	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
612	      method: 'PUT', body: squashBody(task),
613	    });
614	    if (res.status === 200) { merged = true; log(`merged PR #${pr.number} directly — this repo has no pull_request CI to gate on`); }
615	    else log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`);
616	  } else if (action === 'land') {
617	    // The base requires nothing, so auto-merge has no queue to wait behind and
618	    // the arm mutation would be rejected "clean status" — every run, no setting
619	    // to fix (#677). Skip the doomed arm; wait for this run's own dispatched
620	    // evidence and land on it. Delivery must land every cycle, not heal next cycle.
621	    log(`${base} requires nothing to merge — skipping the doomed auto-merge arm;`
622	      + ` waiting for this run's ${expected} dispatched run(s) and landing PR #${pr.number} here`);
623	    merged = await landNow({ token, repo, pr, delivery, expected, task, log });
624	  } else if (action === 'arm' && pr.node_id) {
625	    // Surfaced, not swallowed: a failed arm is why a delivered PR sits open
626	    // forever, and the two usual causes are both fixable repo settings.
627	    const armed = await enableAutoMerge(token, pr.node_id).then(() => true)
628	      .catch((e) => {
629	        log(`could not arm auto-merge on PR #${pr.number}: ${e.message}`
630	          + ' — check Settings → General → "Allow auto-merge", and Settings → Actions → General for a'
631	          + ' workflow-approval requirement parking this PR\'s pull_request run at action_required.'
632	          + ' Waiting for this run\'s dispatched checks and landing it here.');
633	        return false;
634	      });
635	    // Only where the arm failed. A member that armed is GitHub's to land, and
636	    // waiting on it here would add a poll to every healthy repo for nothing.
637	    if (!armed) merged = await landNow({ token, repo, pr, delivery, expected, task, log });
638	  }
639	  return { merged, action };
